public struct FfiConverterTypeFleetSession: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = FleetSession

    public static func lift(_ handle: UInt64) throws -> FleetSession {
        return FleetSession(unsafeFromHandle: handle)
    }

    public static func lower(_ value: FleetSession) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FleetSession {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: FleetSession, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeFleetSession_lift(_ handle: UInt64) throws -> FleetSession {
    return try FfiConverterTypeFleetSession.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeFleetSession_lower(_ value: FleetSession) -> UInt64 {
    return FfiConverterTypeFleetSession.lower(value)
