/**
 * One alert row: a rule against a host, with the evidence its phase was judged on.
 */
public struct AlertViewRecord: Equatable, Hashable {
    /**
     * `"{rule_urn}|{host}"`. Stable identity for a list that mixes rules and hosts.
     */
    public let id: String
    public let ruleId: String
    public let ruleName: String
    /**
     * Core's `AlertRule::describe()`. Show it; do not parse it on either side.
     */
    public let description: String
    public let host: String
    public let metric: MetricKindRecord
    public let comparator: ComparatorRecord
    /**
     * Compared against the normalised *rate* when `is_rate` is true, not against the cumulative
     * total the backend returns. The editor must label the field accordingly.
     */
    public let threshold: Double
    public let phase: AlertPhaseRecord
    public let severity: SeverityRecord
    /**
     * When the BREACH started, not when the alert fired.
     */
    public let breachingSinceMillis: Int64?
    /**
     * `breaching_since + for_duration`; already in the past once `Firing`.
     */
    public let firesAtMillis: Int64?
    /**
     * The reduced value the phase was judged on.
     */
    public let latestValue: Double?
    /**
     * Which mount or interface held it.
     */
    public let seriesLabel: String?
    public let evidence: AlertEvidenceRecord
    public let isRate: Bool
    /**
     * Set when the stored rule failed core's validation — a `NaN` threshold makes every comparator
     * return false, so the rule would otherwise sit in the list silently never firing. Such a rule
     * is SHOWN and NOT evaluated: badging it is the only way an operator ever learns it is broken.
     */
    public let invalidReason: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * `"{rule_urn}|{host}"`. Stable identity for a list that mixes rules and hosts.
         */id: String, ruleId: String, ruleName: String, 
        /**
         * Core's `AlertRule::describe()`. Show it; do not parse it on either side.
         */description: String, host: String, metric: MetricKindRecord, comparator: ComparatorRecord, 
        /**
         * Compared against the normalised *rate* when `is_rate` is true, not against the cumulative
         * total the backend returns. The editor must label the field accordingly.
         */threshold: Double, phase: AlertPhaseRecord, severity: SeverityRecord, 
        /**
         * When the BREACH started, not when the alert fired.
         */breachingSinceMillis: Int64?, 
        /**
         * `breaching_since + for_duration`; already in the past once `Firing`.
         */firesAtMillis: Int64?, 
        /**
         * The reduced value the phase was judged on.
         */latestValue: Double?, 
        /**
         * Which mount or interface held it.
         */seriesLabel: String?, evidence: AlertEvidenceRecord, isRate: Bool, 
        /**
         * Set when the stored rule failed core's validation — a `NaN` threshold makes every comparator
         * return false, so the rule would otherwise sit in the list silently never firing. Such a rule
         * is SHOWN and NOT evaluated: badging it is the only way an operator ever learns it is broken.
         */invalidReason: String?) {
        self.id = id
        self.ruleId = ruleId
        self.ruleName = ruleName
        self.description = description
        self.host = host
        self.metric = metric
        self.comparator = comparator
        self.threshold = threshold
        self.phase = phase
        self.severity = severity
        self.breachingSinceMillis = breachingSinceMillis
        self.firesAtMillis = firesAtMillis
        self.latestValue = latestValue
        self.seriesLabel = seriesLabel
        self.evidence = evidence
        self.isRate = isRate
        self.invalidReason = invalidReason
    }

    

    
}

