        /**
         * The `as_of` the discarded-or-restored cache was written with. `None`, not `0`: a cache that
         * never polled and a cache written at the Unix epoch must not render the same.
         */savedAsOfMillis: Int64?) {
        self.discardedIncompatible = discardedIncompatible
        self.discardedUnreadable = discardedUnreadable
        self.hostsRestored = hostsRestored
        self.evaluationsRestored = evaluationsRestored
        self.savedAsOfMillis = savedAsOfMillis
    }

    

    
}

