public struct FfiConverterTypeTuningWarningRecord: FfiConverterRustBuffer {
    typealias SwiftType = TuningWarningRecord

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> TuningWarningRecord {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .spikeCanFire(ruleId: try FfiConverterString.read(from: &buf), ruleName: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .counterThresholdIsRate(ruleId: try FfiConverterString.read(from: &buf), metric: try FfiConverterTypeMetricKindRecord.read(from: &buf)
        )
        
        case 3: return .selectorMatchesNothing(ruleId: try FfiConverterString.read(from: &buf), ruleName: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: TuningWarningRecord, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .spikeCanFire(ruleId,ruleName):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(ruleId, into: &buf)
            FfiConverterString.write(ruleName, into: &buf)
            
        
        case let .counterThresholdIsRate(ruleId,metric):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(ruleId, into: &buf)
            FfiConverterTypeMetricKindRecord.write(metric, into: &buf)
            
        
        case let .selectorMatchesNothing(ruleId,ruleName):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(ruleId, into: &buf)
            FfiConverterString.write(ruleName, into: &buf)
            
        }
    }
}


